type orders struct{ db *DB }

func (h orders) ServeHTTP(w http.ResponseWriter, r *http.Request) {   // called by net/http
    fmt.Fprint(w, h.db.Lookup(r.URL.Path))
}

func main() {
    http.Handle("/orders/", orders{db})
    http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(204) })
    log.Fatal(http.ListenAndServe(":8080", nil))            // server owns the call flow
}
